(function(){
'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=new Intl.NumberFormat('en-US'),money=new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB',maximumFractionDigits:2}),pct=n=>(n*100).toFixed(1)+'%';
let cloud,session=null,data=null,generation=0,busy=false,aiBusy=false,tab='together',aiIdeas=[];
const allowed=()=>Boolean(session?.user&&!session.loading&&!session.blocked),canGenerate=()=>['admin','importer'].includes(session?.state?.role||session?.role);
const period=NKMDateRange.create($('bundle-period-picker'),{onApply:r=>{$('from').value=r.from;$('to').value=r.to;load();}});
const stores=NKMStorePicker.create($('store'),{defaultValue:'nakama',modes:[{value:'all',label:'All group stores'},{value:'nakama',label:'Nakama brand stores'}]});
const args=()=>({from:$('from').value,to:$('to').value,store:stores.value(),platform:$('platform').value,basis:$('basis').value});
function error(message){$('bundle-error').textContent=message;$('bundle-error').hidden=!message;}
function controls(){const locked=!allowed()||busy||aiBusy;period.disable(locked);stores.disable(locked);for(const id of ['apply','refresh','platform','basis'])$(id).disabled=locked;$('export-bundles').disabled=locked||!data;$('generate-ai').disabled=locked||!data||data.ai?.status!=='available'||!canGenerate()||data.products.length<2;}
function clear(){data=null;aiIdeas=[];$('bundle-dashboard').hidden=true;for(const id of ['pair-rows','idea-grid','plan-result','plan-a','plan-b','basket-count','basket-note','multi-count','multi-note','pair-count','pair-note','idea-count','bundle-coverage','bundle-coverage-note','ai-status','pair-result-count'])$(id).replaceChildren();$('export-bundles').disabled=true;}
function selectTab(next,focus=false){tab=next;for(const b of document.querySelectorAll('[data-bundle-tab]')){const selected=b.dataset.bundleTab===next;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;$('panel-'+b.dataset.bundleTab).hidden=!selected;if(selected&&focus)b.focus();}}
function skuMarkup(sku,prefix=''){const p=data.products.find(p=>p.sku===sku);return `<b class="bundle-sku">${esc(prefix+sku)}<small>${esc(p?.product||sku)}</small></b>`;}
function renderPairs(){if(!data)return;const search=$('pair-search').value.trim().toLowerCase(),min=Number($('pair-min').value),sort=$('pair-sort').value,rows=data.pairs.filter(p=>p.orders>=min&&(!search||p.skus.some(s=>{const product=data.products.find(p=>p.sku===s);return (s+' '+product?.product).toLowerCase().includes(search);}))).sort((a,b)=>b[sort]-a[sort]||b.orders-a.orders||a.id.localeCompare(b.id));
 $('pair-result-count').textContent=count.format(rows.length)+' matching pairings · '+count.format(data.coverage.pairsReturned)+' highest-count pairings available';
 $('pair-rows').innerHTML=rows.map(p=>`<tr><td>${skuMarkup(p.skus[0],'A · ')}<span class="bundle-plus">+</span>${skuMarkup(p.skus[1],'B · ')}<small>${esc(p.compatibility)}</small></td><td>${count.format(p.orders)}<small>${p.orders<3?'Small sample':'Observed orders'}</small></td><td>${pct(p.support)}</td><td>${pct(p.confidenceA)} / ${pct(p.confidenceB)}</td><td>${p.lift.toFixed(2)}×<small>${p.lift>1?'Above independent baseline':'At or below baseline'}</small></td><td><button type="button" class="secondary" data-plan-pair="${esc(p.id)}" aria-label="Plan ${esc(p.skus.join(' plus '))}">Plan</button></td></tr>`).join('')||'<tr><td colspan="6">No pairings match these filters. Try a longer period or a lower minimum shared-order count.</td></tr>';
}
function renderIdeas(){if(!data)return;const rows=[...aiIdeas,...data.ideas];$('idea-count').textContent=count.format(rows.length);
 $('idea-grid').innerHTML=rows.map(p=>`<article class="bundle-idea"><span class="demand-tag">${esc(p.source)}</span><h3>${esc(p.title)}</h3>${skuMarkup(p.skus[0])}<span class="bundle-plus">+</span>${skuMarkup(p.skus[1])}<p class="bundle-evidence">${p.orders==null?'Co-purchase count not in the returned rankings':p.orders?count.format(p.orders)+' observed shared orders':'No observed co-purchases in this period'}</p><p>${esc(p.reason)}</p><p>${esc(p.compatibility)}</p><button type="button" class="secondary" data-plan-pair="${esc(p.id)}">Plan this bundle</button></article>`).join('')||'<p class="chart-empty">No supported ideas yet. Import more order history or select a wider period.</p>';
}
function renderPlan(){if(!data)return;const a=data.products.find(p=>p.sku===$('plan-a').value),b=data.products.find(p=>p.sku===$('plan-b').value),discount=Number($('plan-discount').value),result=$('plan-result');
 if(!a||!b){result.textContent='At least two SKUs are needed to plan a bundle.';return;}if(a.sku===b.sku){result.textContent='Choose two different SKUs.';return;}if($('plan-discount').value===''||!Number.isFinite(discount)||discount<0||discount>90){result.textContent='Choose a discount from 0% to 90%.';return;}
 if(a.averagePrice==null||b.averagePrice==null){result.textContent='An observed price is missing for this pairing. Review your imported pricing data.';return;}
 const reference=a.averagePrice+b.averagePrice,saving=reference*discount/100,fitment=a.fitment&&b.fitment&&a.fitment!==b.fitment?'Different vehicle fitments — review before bundling.':a.category==='Wipers'||b.category==='Wipers'?'Confirm vehicle, blade size and connector fitment.':'Confirm product compatibility.';
 result.innerHTML=[['Reference total',reference],['Trial bundle price',reference-saving],['Customer saving',saving]].map(([label,value])=>`<div><span>${label}</span><strong>${money.format(value)}</strong></div>`).join('')+`<p>${esc(fitment)} ${a.stores.some(s=>b.stores.includes(s))?'':'These SKUs were not observed in the same store. '}Confirm stock and margin before launch.</p>`;
}
function populate(id,values,defaults=[]){const selected=$(id).value;$(id).replaceChildren();for(const [value,label] of [...defaults,...values.map(v=>[v,id==='store'?nkmStoreLabel(v):v])]){const o=document.createElement('option');o.value=value;o.textContent=label;$(id).append(o);}if([...$(id).options].some(o=>o.value===selected))$(id).value=selected;if(id==='store')stores.sync();}
function render(){if(!data||!allowed())return;const {totals:t,coverage:c}=data;$('bundle-dashboard').hidden=false;$('bundle-badge').textContent=t.orders?'Imported order patterns':'No matching baskets';$('basket-count').textContent=count.format(t.orders);$('basket-note').textContent=count.format(c.emptyOrders)+' selected orders had no eligible SKU lines';$('multi-count').textContent=count.format(t.multiSkuOrders);$('multi-note').textContent=pct(t.orders?t.multiSkuOrders/t.orders:0)+' of analyzed baskets';$('pair-count').textContent=count.format(t.pairCount);$('pair-note').textContent=count.format(c.analyzedSkus)+' SKUs analyzed';
 populate('store',data.options.stores,[['nakama','Nakama brand stores'],['all','All group stores']]);populate('platform',data.options.platforms,[['','All marketplaces']]);
 for(const id of ['plan-a','plan-b']){populate(id,data.products.map(p=>p.sku));for(const option of $(id).options){const p=data.products.find(p=>p.sku===option.value);option.textContent=p.sku+' · '+p.product;}}if($('plan-a').value===$('plan-b').value&&data.products.length>1)$('plan-b').value=data.products[1].sku;
 $('ai-status').textContent=data.ai?.status==='available'?(canGenerate()?'Generate fresh AI ideas for these filters. Ideas need testing; they do not predict sales.':'An administrator or importer can generate AI ideas.'):'AI suggestions are not connected yet. Purchase-pattern and category ideas are available below.';
 $('bundle-coverage').textContent=`${data.filters.from} to ${data.filters.to} · ${count.format(t.orders)} baskets · ${count.format(c.analyzedSkus)} of ${count.format(t.skuCount)} observed SKUs · ${count.format(c.coveredOrders)} baskets contain an analyzed SKU`;
 const missing=[];for(let d=data.filters.from.slice(0,7)+'-01';d<=data.filters.to;){if(!data.months.includes(d.slice(0,7)))missing.push(d.slice(0,7));const date=new Date(d+'T00:00:00Z');date.setUTCMonth(date.getUTCMonth()+1);d=date.toISOString().slice(0,10);}
 $('bundle-coverage-note').textContent=(t.skuCount>c.analyzedSkus?'Pairings are limited to the '+c.skuLimit+' most-ordered SKUs. ':'')+(t.pairCount>c.pairsReturned?'Only the '+c.pairsReturned+' highest-count pairings are returned. ':'')+(missing.length?'Months without imported reports: '+missing.join(', ')+'. ':'')+(c.ignoredLines?count.format(c.ignoredLines)+' lines with missing SKUs or invalid quantities were excluded. ':'')+'Imported coverage may be incomplete. Bundle reference prices are quantity-weighted observed unit prices; stock and margin are unverified.';
 renderPairs();renderIdeas();renderPlan();selectTab(tab);controls();
}
async function load(){if(!allowed()||busy||aiBusy)return;const filters=args();if(!filters.from||!filters.to||filters.from>filters.to){error('Choose valid From and To dates.');return;}const token=++generation;clear();error('');busy=true;controls();$('bundle-status').textContent='Calculating SKU pairings from shared order history…';try{const report=await cloud.bundleInsights(filters);if(token!==generation||!allowed())return;if(report.kind!=='bundles'||report.version!==1)throw Error('Bundle reporting is awaiting activation. Ask your administrator to update the reporting service, then Refresh.');data=report;render();$('bundle-status').textContent=report.coverage.firstDate?'Matching imported order dates: '+report.coverage.firstDate+' to '+report.coverage.lastDate:'No matching order baskets.';}catch(e){if(token!==generation)return;clear();if(/permission-denied|unauthenticated/.test(String(e.code))){await sessionChanged({user:session?.user,blocked:true,error:cloud.authError(e,'workspace')});return;}error(e.message||'Bundle reporting could not load. Try Refresh.');$('bundle-status').textContent='Bundle reporting unavailable.';}finally{if(token===generation){busy=false;controls();}}}
async function generate(){if(!allowed()||aiBusy||busy||!data||data.ai?.status!=='available'||!canGenerate())return;const token=generation,filters=data.filters,revision=data.revision;aiBusy=true;controls();error('');$('ai-status').textContent='Generating AI bundle ideas…';try{const report=await cloud.bundleIdeas(filters);if(token!==generation||!allowed())return;if(report.kind!=='bundles'||report.revision!==revision)throw Error('Order history changed. Refresh the analysis before generating ideas.');if(report.ai?.status!=='ready')throw Error('AI ideas are unavailable for this selection.');aiIdeas=report.ai.ideas;renderIdeas();$('ai-status').textContent=aiIdeas.length+' AI ideas generated for the applied filters. Review compatibility and margin before testing.';}catch(e){if(token!==generation)return;if(/permission-denied|unauthenticated/.test(String(e.code))){await sessionChanged({user:session?.user,blocked:true,error:cloud.authError(e,'workspace')});return;}error(e.message||'AI suggestions could not load.');$('ai-status').textContent='AI ideas unavailable. Purchase-pattern suggestions are still available.';}finally{if(token===generation){aiBusy=false;controls();}}}
async function sessionChanged(next){generation++;busy=aiBusy=false;clear();error('');session=next;document.documentElement.classList.toggle('auth-pending',Boolean(next?.loading));const ok=allowed();document.body.classList.toggle('auth-open',!ok);$('auth-gate').hidden=ok;$('auth-form').hidden=Boolean(next?.loading||next?.setup||next?.blocked);$('auth-submit').disabled=Boolean(next?.loading||next?.setup);$('auth-retry').hidden=!next?.blocked;$('auth-signout').hidden=!next?.blocked;$('auth-error').textContent=next?.error||'';$('auth-title').textContent=next?.loading?'Connecting…':next?.setup?'Connect your workspace':next?.blocked?'Access needed':'Sign in';$('auth-message').textContent=next?.loading?'Checking your account and shared reports.':next?.blocked?'Workspace access needs attention.':'Access your shared bundle insights.';$('bundle-status').textContent='';$('bundle-badge').textContent='Not connected';controls();
 if(!ok){period.clear();stores.set('nakama');populate('store',[],[['nakama','Nakama brand stores'],['all','All group stores']]);populate('platform',[],[['','All marketplaces']]);stores.clear();$('from').value=$('to').value='';return;}
 $('auth-password').value='';hidePassword();const months=next.state?.months||[],parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit'}).formatToParts(new Date()),latest=months.at(-1)||['year','month'].map(k=>parts.find(p=>p.type===k).value).join('-');
 const [y,m]=latest.split('-').map(Number);$('from').value=latest+'-01';$('to').value=new Date(Date.UTC(y,m,0)).toISOString().slice(0,10);period.setYears(months);period.set({from:$('from').value,to:$('to').value});await load();
}
function hidePassword(){$('auth-password').type='password';$('auth-show-password').textContent='Show';$('auth-show-password').setAttribute('aria-label','Show password');$('auth-show-password').setAttribute('aria-pressed','false');}
$('auth-show-password').onclick=()=>{const show=$('auth-password').type==='password';$('auth-password').type=show?'text':'password';$('auth-show-password').textContent=show?'Hide':'Show';$('auth-show-password').setAttribute('aria-label',show?'Hide password':'Show password');$('auth-show-password').setAttribute('aria-pressed',String(show));};
$('auth-form').onsubmit=async e=>{e.preventDefault();if(!cloud)return;$('auth-submit').disabled=true;try{await cloud.signIn($('auth-email').value,$('auth-password').value);}catch(e){$('auth-error').textContent=cloud.authError(e);}finally{$('auth-submit').disabled=Boolean(session?.loading);}};
$('auth-retry').onclick=()=>cloud.retrySession().catch(e=>{$('auth-error').textContent=cloud.authError(e,'workspace');});
async function logout(){await sessionChanged(null);try{await cloud.signOut();}catch(e){$('auth-error').textContent=e.message;}}
$('signout').onclick=$('auth-signout').onclick=logout;$('refresh').onclick=()=>{cloud.clearReportCache?.();load();};$('bundle-filters').onsubmit=e=>{e.preventDefault();load();};$('store').onchange=()=>load();$('generate-ai').onclick=generate;
for(const id of ['pair-search','pair-min','pair-sort'])$(id).addEventListener(id==='pair-search'?'input':'change',renderPairs);
for(const b of document.querySelectorAll('[data-bundle-tab]')){b.onclick=()=>selectTab(b.dataset.bundleTab);b.onkeydown=e=>{const tabs=['together','ideas','plan'];let index=tabs.indexOf(b.dataset.bundleTab);if(e.key==='ArrowRight')index=(index+1)%3;else if(e.key==='ArrowLeft')index=(index+2)%3;else if(e.key==='Home')index=0;else if(e.key==='End')index=2;else return;e.preventDefault();selectTab(tabs[index],true);};}
document.addEventListener('click',e=>{const button=e.target.closest('[data-plan-pair]');if(!button||!data||!allowed())return;const skus=JSON.parse(button.dataset.planPair);$('plan-a').value=skus[0];$('plan-b').value=skus[1];renderPlan();selectTab('plan',true);$('panel-plan').scrollIntoView?.({block:'start',behavior:'smooth'});});
$('bundle-plan').onsubmit=e=>e.preventDefault();for(const id of ['plan-a','plan-b','plan-discount'])$(id).addEventListener('input',renderPlan);
$('export-bundles').onclick=()=>{if(!data||!allowed())return;const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';},rows=[['SKU A','SKU B','Shared orders','All-order share','A to B rate','B to A rate','Lift','Reference price THB','Compatibility'],...data.pairs.map(p=>[...p.skus,p.orders,p.support,p.confidenceA,p.confidenceB,p.lift,p.referencePrice,p.compatibility])],csv='\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='nakama-bundles-'+data.filters.from+'-'+data.filters.to+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
import('./cloud.js?v=bundles-20261007').then(async api=>{cloud=api;await api.start(sessionChanged,()=>{},()=>{if(allowed())$('bundle-status').textContent='New shared orders are available. Refresh to recalculate.';});}).catch(()=>{sessionChanged({setup:true});$('auth-error').textContent='The sign-in service could not load. Refresh to retry.';});
})();
